parameters.jsCode:
const i = $json;
const text = String(i.text || '').trim();
return {
  text: text,
  hasText: text.length > 0,
  charCount: text.length,
  language: i.language || 'English',
  audience: i.audience || 'General business audience',
  maxWords: Number(i.maxWords) > 0 ? Number(i.maxWords) : 80
};

parameters.text:
=Summarise the text below for a {{ $json.audience }} in {{ $json.language }}, in at most {{ $json.maxWords }} words. Return a plain-language summary, 3-5 key bullet points, the overall tone of the original (positive, neutral or negative), and your confidence (high, medium or low) in whether the text was clear enough to summarise faithfully. Never add facts that are not present.

Text:
{{ $json.text }}

parameters.jsCode:
const src = $json.output || {};
const meta = $('Apply Defaults').item.json;
const bullets = Array.isArray(src.bullets) ? src.bullets : [];
return {
  ok: true,
  summary: src.summary || '',
  bullets: bullets,
  bulletText: bullets.map(function (b) { return '- ' + b; }).join('\n'),
  tone: String(src.tone || 'neutral').toLowerCase(),
  confidence: String(src.confidence || 'medium').toLowerCase(),
  language: meta.language,
  sourceChars: meta.charCount,
  error: ''
};
